/// `timelib_tz_get_wrapper`: resolves a zone identifier (exactly as written in the input) to zone data.
///
/// PHP passes `php_date_parse_tzfile_wrapper()`, a per-name cache in front of `timelib_parse_tzfile()`; see
/// [`TzCache::get`].
pub type TzGetWrapper<'a> = dyn FnMut(&str, &TzDb) -> Option<Arc<TzInfo>> + 'a;

