/// The byte at `p`, or NUL past the end (C would read the terminator or beyond).
#[inline]
pub(crate) fn at(b: &[u8], p: usize) -> u8 {
    b.get(p).copied().unwrap_or(0)
}

/// C `isspace()` in the C/C.UTF-8 locale.
#[inline]
fn is_c_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// `strtol(s, NULL, 10)` / `strtoll()` as glibc implements them, saturating on overflow. Returns the value and
/// whether it overflowed (`errno == ERANGE`).
pub(crate) fn c_strtoll(b: &[u8], start: usize) -> (i64, bool) {
    let mut p = start;
    while is_c_space(at(b, p)) {
        p += 1;
    }
    let mut neg = false;
    if at(b, p) == b'+' || at(b, p) == b'-' {
        neg = at(b, p) == b'-';
        p += 1;
    }
    let mut acc: i128 = 0;
    let mut overflow = false;
    while at(b, p).is_ascii_digit() {
        if !overflow {
            acc = acc * 10 + i128::from(at(b, p) - b'0');
            if acc > i128::from(i64::MAX) + 1 {
                overflow = true;
            }
        }
        p += 1;
    }
    let v = if neg { -acc } else { acc };
    if overflow || v > i128::from(i64::MAX) || v < i128::from(i64::MIN) {
        (if neg { i64::MIN } else { i64::MAX }, true)
    } else {
        (v as i64, false)
    }
}

/// `strtod()` on a buffer that only contains digits, `.` and `:`: the longest `[0-9]*(\.[0-9]*)?` prefix with at
/// least one digit (glibc and Rust both round correctly), else 0.
fn c_strtod_simple(b: &[u8]) -> f64 {
    let mut end = 0;
    let mut digits = 0;
    while end < b.len() && b[end].is_ascii_digit() {
        end += 1;
        digits += 1;
    }
    if end < b.len() && b[end] == b'.' {
        let mut e2 = end + 1;
        let mut frac_digits = 0;
        while e2 < b.len() && b[e2].is_ascii_digit() {
            e2 += 1;
            frac_digits += 1;
        }
        if digits + frac_digits > 0 {
            end = e2;
            digits += frac_digits;
        }
    }
    if digits == 0 {
        return 0.0;
    }
    std::str::from_utf8(&b[..end])
        .ok()
        .and_then(|s| s.parse::<f64>().ok())
        .unwrap_or(0.0)
}

/// glibc `pow(10, k)` for integer `k`. Checked against the oracle for k in -340..=10: glibc returns the
/// correctly rounded value, which Rust's float parsing also produces.
pub(crate) fn pow10(k: i64) -> f64 {
    if k < -400 {
        return 0.0;
    }
    if k > 400 {
        return f64::INFINITY;
    }
    format!("1e{k}").parse::<f64>().unwrap_or(0.0)
}

/// C conversion of a double to `timelib_sll`: truncation; out-of-range values give `i64::MIN` on x86-64.
pub(crate) fn f64_to_sll(v: f64) -> i64 {
    if v.is_nan() || v >= 9_223_372_036_854_775_808.0 || v < -9_223_372_036_854_775_808.0 {
        i64::MIN
    } else {
        v as i64
    }
}

/// C conversion of a double to `timelib_ull` (x86-64 gcc: values ≥ 2^63 are converted via subtraction; values
/// out of range wrap like `i64::MIN`).
pub(crate) fn f64_to_ull(v: f64) -> u64 {
    if v.is_nan() {
        return 0x8000_0000_0000_0000;
    }
    if v >= 9_223_372_036_854_775_808.0 {
        if v < 18_446_744_073_709_551_616.0 {
            return (v - 9_223_372_036_854_775_808.0) as u64 ^ 0x8000_0000_0000_0000;
        }
        return 0x8000_0000_0000_0000;
    }
    f64_to_sll(v) as u64
}

/// `struct _Scanner` (the fields the port needs).
pub(crate) struct Scanner<'a> {
    /// The trimmed input followed by `YYMAXFILL` NUL bytes.
    pub(crate) str: Vec<u8>,
    /// `YYLIMIT`.
    pub(crate) lim: usize,
    /// Where the next token starts.
    pub(crate) cur: usize,
    /// Start of the current token (`NULL` before the first one).
    pub(crate) tok: Option<usize>,
    pub(crate) errors: ErrorContainer,
    pub(crate) time: Time,
    pub(crate) tzdb: &'a TzDb,
}

impl Scanner<'_> {
    fn message(&self, error_code: i32, error: &'static str) -> ErrorMessage {
        let (position, character) = match self.tok {
            Some(t) => (t as i32, at(&self.str, t)),
            None => (0, 0),
        };
        ErrorMessage {
            error_code,
            position,
            character,
            message: error,
        }
    }

    /// `add_warning()`.
    pub(crate) fn add_warning(&mut self, error_code: i32, error: &'static str) {
        if self.errors.warning_messages.len() >= MAX_ERRORS {
            return;
        }
        let m = self.message(error_code, error);
        self.errors.warning_messages.push(m);
    }

    /// `add_error()`.
    pub(crate) fn add_error(&mut self, error_code: i32, error: &'static str) {
        if self.errors.error_messages.len() >= MAX_ERRORS {
            return;
        }
        let m = self.message(error_code, error);
        self.errors.error_messages.push(m);
    }

    /// `timelib_string()`: a NUL-terminated copy of the current token `[tok, cur)`.
    pub(crate) fn token(&self) -> Vec<u8> {
        let tok = self.tok.unwrap_or(0);
        let mut v = self.str[tok..self.cur].to_vec();
        v.push(0);
        v
    }
}

/// `add_pbf_warning()` (format parser: position relative to the start of the input).
fn add_pbf_warning(
    errors: &mut ErrorContainer,
    error_code: i32,
    error: &'static str,
    sptr: &[u8],
    cptr: usize,
) {
    if errors.warning_messages.len() >= MAX_ERRORS {
        return;
    }
    errors.warning_messages.push(ErrorMessage {
        error_code,
        position: cptr as i32,
        character: at(sptr, cptr),
        message: error,
    });
}

/// `add_pbf_error()`.
fn add_pbf_error(
    errors: &mut ErrorContainer,
    error_code: i32,
    error: &'static str,
    sptr: &[u8],
    cptr: usize,
) {
    if errors.error_messages.len() >= MAX_ERRORS {
        return;
    }
    errors.error_messages.push(ErrorMessage {
        error_code,
        position: cptr as i32,
        character: at(sptr, cptr),
        message: error,
    });
}

/// `timelib_meridian()`: the hour correction for `am`/`pm` (the regex guarantees a meridian is present).
pub(crate) fn meridian(b: &[u8], ptr: &mut usize, h: i64) -> i64 {
    let mut retval = 0;
    // `strchr("AaPp", c)` also matches the terminating NUL.
    while !matches!(at(b, *ptr), b'A' | b'a' | b'P' | b'p' | 0) {
        *ptr += 1;
    }
    if at(b, *ptr) == b'a' || at(b, *ptr) == b'A' {
        if h == 12 {
            retval = -12;
        }
    } else if h != 12 {
        retval = 12;
    }
    *ptr += 1;
    if at(b, *ptr) == b'.' {
        *ptr += 1;
    }
    if at(b, *ptr) == b'M' || at(b, *ptr) == b'm' {
        *ptr += 1;
    }
    if at(b, *ptr) == b'.' {
        *ptr += 1;
    }
    retval
}

/// `timelib_meridian_with_check()`.
fn meridian_with_check(b: &[u8], ptr: &mut usize, h: i64) -> i64 {
    let mut retval = 0;
    while at(b, *ptr) != 0 && !matches!(at(b, *ptr), b'A' | b'a' | b'P' | b'p') {
        *ptr += 1;
    }
    if at(b, *ptr) == 0 {
        return UNSET;
    }
    if at(b, *ptr) == b'a' || at(b, *ptr) == b'A' {
        if h == 12 {
            retval = -12;
        }
    } else if h != 12 {
        retval = 12;
    }
    *ptr += 1;
    if at(b, *ptr) == b'.' {
        *ptr += 1;
        if at(b, *ptr) != b'm' && at(b, *ptr) != b'M' {
            return UNSET;
        }
        *ptr += 1;
        if at(b, *ptr) != b'.' {
            return UNSET;
        }
        *ptr += 1;
    } else if at(b, *ptr) == b'm' || at(b, *ptr) == b'M' {
        *ptr += 1;
    } else {
        return UNSET;
    }
    retval
}

/// `timelib_get_nr_ex()`: skips to the next digit and reads at most `max_length` digits. `scanned_length` is
/// only written when a number is found.
pub(crate) fn get_nr_ex(
    b: &[u8],
    ptr: &mut usize,
    max_length: i32,
    scanned_length: &mut i32,
) -> i64 {
    while !at(b, *ptr).is_ascii_digit() {
        if at(b, *ptr) == 0 {
            return UNSET;
        }
        *ptr += 1;
    }
    let begin = *ptr;
    let mut len = 0;
    while at(b, *ptr).is_ascii_digit() && len < max_length {
        *ptr += 1;
        len += 1;
    }
    *scanned_length = (*ptr - begin) as i32;
    let mut digits = b[begin..*ptr].to_vec();
    digits.push(0);
    c_strtoll(&digits, 0).0
}

/// `timelib_get_nr()`.
pub(crate) fn get_nr(b: &[u8], ptr: &mut usize, max_length: i32) -> i64 {
    let mut unused = 0;
    get_nr_ex(b, ptr, max_length, &mut unused)
}

/// `timelib_skip_day_suffix()`.
pub(crate) fn skip_day_suffix(b: &[u8], ptr: &mut usize) {
    if is_c_space(at(b, *ptr)) {
        return;
    }
    let rest = b.get(*ptr..).unwrap_or(&[]);
    if strncasecmp(rest, b"nd", 2) == 0
        || strncasecmp(rest, b"rd", 2) == 0
        || strncasecmp(rest, b"st", 2) == 0
        || strncasecmp(rest, b"th", 2) == 0
    {
        *ptr += 2;
    }
}

/// `timelib_get_frac_nr()`: a fraction like `.5` or `:123456` as microseconds, computed in doubles like C.
pub(crate) fn get_frac_nr(b: &[u8], ptr: &mut usize) -> i64 {
    while at(b, *ptr) != b'.' && at(b, *ptr) != b':' && !at(b, *ptr).is_ascii_digit() {
        if at(b, *ptr) == 0 {
            return UNSET;
        }
        *ptr += 1;
    }
    let begin = *ptr;
    while at(b, *ptr) == b'.' || at(b, *ptr) == b':' || at(b, *ptr).is_ascii_digit() {
        *ptr += 1;
    }
    let end = *ptr;
    let s = &b[begin + 1..end];
    let tmp_nr = c_strtod_simple(s) * pow10(7 - (end - begin) as i64);
    f64_to_sll(tmp_nr)
}

/// `timelib_get_signed_nr()`: an optionally signed number of at most `max_length` digits; records "Found
/// unexpected data" / "Number out of range" errors on the scanner.
pub(crate) fn get_signed_nr(
    s: &mut Scanner<'_>,
    b: &[u8],
    ptr: &mut usize,
    max_length: i32,
) -> i64 {
    // Skip over non-numeric chars
    while !at(b, *ptr).is_ascii_digit() && at(b, *ptr) != b'+' && at(b, *ptr) != b'-' {
        if at(b, *ptr) == 0 {
            s.add_error(ERR_UNEXPECTED_DATA, "Found unexpected data");
            return 0;
        }
        *ptr += 1;
    }

    // Sign + digits, fed to strtoll()
    let mut str = Vec::with_capacity(max_length as usize + 2);
    str.push(b'+');

    while at(b, *ptr) == b'+' || at(b, *ptr) == b'-' {
        if at(b, *ptr) == b'-' {
            str[0] = if str[0] == b'+' { b'-' } else { b'+' };
        }
        *ptr += 1;
    }

    while !at(b, *ptr).is_ascii_digit() {
        if at(b, *ptr) == 0 {
            s.add_error(ERR_UNEXPECTED_DATA, "Found unexpected data");
            return 0;
        }
        *ptr += 1;
    }

    let mut len = 0;
    while at(b, *ptr).is_ascii_digit() && len < max_length {
        str.push(at(b, *ptr));
        *ptr += 1;
        len += 1;
    }

    let (tmp_nr, range_error) = c_strtoll(&str, 0);
    if range_error {
        s.add_error(ERR_NUMBER_OUT_OF_RANGE, "Number out of range");
        return 0;
    }
    tmp_nr
}

/// `timelib_lookup_relative_text()`.
fn lookup_relative_text(b: &[u8], ptr: &mut usize, behavior: &mut i32) -> i64 {
    let begin = *ptr;
    while at(b, *ptr).is_ascii_alphabetic() {
        *ptr += 1;
    }
    let word = &b[begin..*ptr];
    let mut value = 0;
    for &(name, kind, v) in RELTEXT_LOOKUP.iter() {
        if strcasecmp(word, name) == 0 {
            value = v;
            *behavior = kind;
        }
    }
    value
}

/// `timelib_get_relative_text()`.
pub(crate) fn get_relative_text(b: &[u8], ptr: &mut usize, behavior: &mut i32) -> i64 {
    while matches!(at(b, *ptr), b' ' | b'\t' | b'-' | b'/') {
        *ptr += 1;
    }
    lookup_relative_text(b, ptr, behavior)
}

/// `timelib_lookup_month()`.
pub(crate) fn lookup_month(b: &[u8], ptr: &mut usize) -> i64 {
    let begin = *ptr;
    while at(b, *ptr).is_ascii_alphabetic() {
        *ptr += 1;
    }
    let word = &b[begin..*ptr];
    let mut value = 0;
    for &(name, v) in MONTH_LOOKUP.iter() {
        if strcasecmp(word, name) == 0 {
            value = v;
        }
    }
    value
}

/// `timelib_get_month()`.
pub(crate) fn get_month(b: &[u8], ptr: &mut usize) -> i64 {
    while matches!(at(b, *ptr), b' ' | b'\t' | b'-' | b'.' | b'/') {
        *ptr += 1;
    }
    lookup_month(b, ptr)
}

/// `timelib_eat_spaces()`: spaces, tabs, NBSP (`C2 A0`) and NNBSP (`E2 80 AF`).
pub(crate) fn eat_spaces(b: &[u8], ptr: &mut usize) {
    loop {
        if at(b, *ptr) == b' ' || at(b, *ptr) == b'\t' {
            *ptr += 1;
            continue;
        }
        if at(b, *ptr) == 0xe2 && at(b, *ptr + 1) == 0x80 && at(b, *ptr + 2) == 0xaf {
            *ptr += 3;
            continue;
        }
        if at(b, *ptr) == 0xc2 && at(b, *ptr + 1) == 0xa0 {
            *ptr += 2;
            continue;
        }
        break;
    }
}

/// `timelib_eat_until_separator()`.
fn eat_until_separator(b: &[u8], ptr: &mut usize) {
    *ptr += 1;
    // `strchr(" \t.,:;/-0123456789", c)` also matches the terminating NUL.
    while !matches!(
        at(b, *ptr),
        b' ' | b'\t' | b'.' | b',' | b':' | b';' | b'/' | b'-' | b'0'..=b'9' | 0
    ) {
        *ptr += 1;
    }
}

/// `timelib_lookup_relunit()`.
pub(crate) fn lookup_relunit(b: &[u8], ptr: &mut usize) -> Option<&'static RelUnit> {
    let begin = *ptr;
    while !matches!(
        at(b, *ptr),
        0 | b' ' | b',' | b'\t' | b';' | b':' | b'/' | b'.' | b'-' | b'(' | b')'
    ) {
        *ptr += 1;
    }
    let word = &b[begin..*ptr];
    RELUNIT_LOOKUP[..RELUNIT_LOOKUP.len() - 1]
        .iter()
        .find(|tp| strcasecmp(word, tp.name) == 0)
}

impl RelUnit {
    /// The weekday number or special type stored in the table.
    pub(crate) fn multiplier(&self) -> i32 {
        self.multiplier
    }
}

/// `add_with_overflow()`: PHP's build has `__builtin_saddll_overflow`, so overflow is reported (and the wrapped
/// sum kept).
fn add_with_overflow(
    s: &mut Scanner<'_>,
    field: fn(&mut Time) -> &mut i64,
    amount: i64,
    multiplier: i32,
) {
    let e = field(&mut s.time);
    let (r, o) = e.overflowing_add(amount.wrapping_mul(i64::from(multiplier)));
    *e = r;
    if o {
        s.add_error(ERR_NUMBER_OUT_OF_RANGE, "Number out of range");
    }
}

/// `TIMELIB_UNHAVE_TIME()`.
pub(crate) fn unhave_time(t: &mut Time) {
    t.have_time = 0;
    t.h = 0;
    t.i = 0;
    t.s = 0;
    t.us = 0;
}

/// `TIMELIB_UNHAVE_DATE()`.
pub(crate) fn unhave_date(t: &mut Time) {
    t.have_date = 0;
    t.d = 0;
    t.m = 0;
    t.y = 0;
}

/// `timelib_set_relative()`: applies `amount` of the unit that follows `ptr`.
pub(crate) fn set_relative(
    b: &[u8],
    ptr: &mut usize,
    amount: i64,
    behavior: i32,
    s: &mut Scanner<'_>,
    time_part: i32,
) {
    let Some(relunit) = lookup_relunit(b, ptr) else {
        return;
    };

    match relunit.unit {
        TIMELIB_MICROSEC => {
            add_with_overflow(s, |t| &mut t.relative.us, amount, relunit.multiplier)
        }
        TIMELIB_SECOND => add_with_overflow(s, |t| &mut t.relative.s, amount, relunit.multiplier),
        TIMELIB_MINUTE => add_with_overflow(s, |t| &mut t.relative.i, amount, relunit.multiplier),
        TIMELIB_HOUR => add_with_overflow(s, |t| &mut t.relative.h, amount, relunit.multiplier),
        TIMELIB_DAY => add_with_overflow(s, |t| &mut t.relative.d, amount, relunit.multiplier),
        TIMELIB_MONTH => add_with_overflow(s, |t| &mut t.relative.m, amount, relunit.multiplier),
        TIMELIB_YEAR => add_with_overflow(s, |t| &mut t.relative.y, amount, relunit.multiplier),
        TIMELIB_WEEKDAY_UNIT => {
            s.time.have_relative = 1;
            s.time.relative.have_weekday_relative = 1;
            if time_part != TIME_PART_KEEP {
                unhave_time(&mut s.time);
            }
            let k = if amount > 0 { amount - 1 } else { amount };
            s.time.relative.d = s.time.relative.d.wrapping_add(k.wrapping_mul(7));
            s.time.relative.weekday = relunit.multiplier;
            s.time.relative.weekday_behavior = behavior;
        }
        TIMELIB_SPECIAL => {
            s.time.have_relative = 1;
            s.time.relative.have_special_relative = 1;
            if time_part != TIME_PART_KEEP {
                unhave_time(&mut s.time);
            }
            s.time.relative.special.kind = relunit.multiplier as u32;
            s.time.relative.special.amount = amount;
        }
        _ => {}
    }
}

/// `timelib_lookup_abbr()`: reads `[A-Za-z0-9/_+-]*` and looks it up as an abbreviation. Returns the offset
/// (without DST), and the word.
fn lookup_abbr(b: &[u8], ptr: &mut usize, dst: &mut i32, found: &mut bool) -> (i64, Vec<u8>) {
    let begin = *ptr;
    while matches!(at(b, *ptr), b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'/' | b'_' | b'-' | b'+')
    {
        *ptr += 1;
    }
    let word = b[begin..*ptr].to_vec();
    let mut value = 0;
    if word.len() < MAX_ABBR_LEN
        && let Some(tp) = abbr_search(&word, -1, 0)
    {
        value = i64::from(tp.gmtoffset);
        *dst = tp.dst;
        value -= i64::from(tp.dst) * 3600;
        *found = true;
    } else {
        *found = false;
    }
    (value, word)
}

/// `sHOUR()`.
fn s_hour(a: i64) -> i64 {
    i64::from(a.wrapping_mul(3600) as i32)
}

/// `sMIN()`.
fn s_min(a: i64) -> i64 {
    i64::from(a.wrapping_mul(60) as i32)
}

/// `timelib_parse_tz_cor()`: `H`, `HH`, `H:M`, `HHMM`, `HH:MM`, `HHMMSS`, `HH:MM:SS`.
fn parse_tz_cor(b: &[u8], ptr: &mut usize, tz_not_found: &mut bool) -> i64 {
    let begin = *ptr;
    *tz_not_found = true;

    while at(b, *ptr).is_ascii_digit() || at(b, *ptr) == b':' {
        *ptr += 1;
    }
    let end = *ptr;
    let strtol = |p: usize| c_strtoll(b, p).0;
    match end - begin {
        1 | 2 => {
            *tz_not_found = false;
            return s_hour(strtol(begin));
        }
        3 | 4 => {
            if at(b, begin + 1) == b':' {
                *tz_not_found = false;
                return s_hour(strtol(begin)) + s_min(strtol(begin + 2));
            } else if at(b, begin + 2) == b':' {
                *tz_not_found = false;
                return s_hour(strtol(begin)) + s_min(strtol(begin + 3));
            } else {
                *tz_not_found = false;
                let tmp = strtol(begin);
                return s_hour(tmp / 100) + s_min(tmp % 100);
            }
        }
        5 if at(b, begin + 2) == b':' => {
            *tz_not_found = false;
            return s_hour(strtol(begin)) + s_min(strtol(begin + 3));
        }
        6 => {
            *tz_not_found = false;
            let tmp = strtol(begin);
            return s_hour(tmp / 10000) + s_min((tmp / 100) % 100) + (tmp % 100);
        }
        8 if at(b, begin + 2) == b':' && at(b, begin + 5) == b':' => {
            *tz_not_found = false;
            return s_hour(strtol(begin)) + s_min(strtol(begin + 3)) + strtol(begin + 6);
        }
        _ => {}
    }
    0
}

/// `timelib_parse_tz_minutes()`: `+mmm` / `-mmm` (not mapped by PHP's default format specifiers).
fn parse_tz_minutes(b: &[u8], ptr: &mut usize, t: &mut Time) -> i64 {
    let mut retval = UNSET;
    let begin = *ptr;

    // First character must be +/-
    if at(b, *ptr) != b'+' && at(b, *ptr) != b'-' {
        return retval;
    }

    *ptr += 1;
    while at(b, *ptr).is_ascii_digit() {
        *ptr += 1;
    }

    if at(b, begin) == b'+' {
        t.is_localtime = 1;
        t.zone_type = ZONETYPE_OFFSET;
        t.dst = 0;
        retval = s_min(c_strtoll(b, begin + 1).0);
    } else if at(b, begin) == b'-' {
        t.is_localtime = 1;
        t.zone_type = ZONETYPE_OFFSET;
        t.dst = 0;
        retval = -s_min(c_strtoll(b, begin + 1).0);
    }
    retval
}

/// Port of `timelib_parse_zone()` (PHPSRC/ext/date/lib/parse_date.re): parses a zone at `ptr` in the
/// NUL-terminated buffer `b` (offset, abbreviation or identifier) into `t`, returning the UTC offset.
///
/// `dst` receives the abbreviation's DST flag when one is found (C passes `&t->dst` from the scanner, where the
/// write is mirrored into `t` anyway, and a separate variable from `DateTimeZone::__construct()`).
/// `tz_not_found` is set when nothing matched.
pub fn parse_zone(
    b: &[u8],
    ptr: &mut usize,
    dst: &mut i32,
    t: &mut Time,
    tz_not_found: &mut bool,
    tzdb: &TzDb,
    tz_wrapper: &mut TzGetWrapper<'_>,
) -> i64 {
    let mut paren_count: usize = 0;

    *tz_not_found = false;

    while at(b, *ptr) == b' ' || at(b, *ptr) == b'\t' || at(b, *ptr) == b'(' {
        paren_count += usize::from(at(b, *ptr) == b'(');
        *ptr += 1;
    }
    if at(b, *ptr) == b'G'
        && at(b, *ptr + 1) == b'M'
        && at(b, *ptr + 2) == b'T'
        && (at(b, *ptr + 3) == b'+' || at(b, *ptr + 3) == b'-')
    {
        *ptr += 3;
    }
    let retval = if at(b, *ptr) == b'+' {
        *ptr += 1;
        t.is_localtime = 1;
        t.zone_type = ZONETYPE_OFFSET;
        t.dst = 0;

        parse_tz_cor(b, ptr, tz_not_found)
    } else if at(b, *ptr) == b'-' {
        *ptr += 1;
        t.is_localtime = 1;
        t.zone_type = ZONETYPE_OFFSET;
        t.dst = 0;

        -parse_tz_cor(b, ptr, tz_not_found)
    } else {
        let mut found = false;
        let mut found_count = 0;

        t.is_localtime = 1;

        // First, we lookup by abbreviation only
        let (offset, tz_abbr) = lookup_abbr(b, ptr, dst, &mut found);
        if found {
            t.zone_type = ZONETYPE_ABBR;
            t.dst = *dst;
            t.tz_abbr_update(&String::from_utf8_lossy(&tz_abbr));
            found_count = 1;
        }

        // Otherwise, we look if we have a TimeZone identifier
        if !found || tz_abbr == b"UTC" {
            let name = String::from_utf8_lossy(&tz_abbr);
            if let Some(res) = tz_wrapper(&name, tzdb) {
                t.tz_info = Some(res);
                t.zone_type = ZONETYPE_ID;
                found_count += 1;
            }
        }
        *tz_not_found = found_count == 0;
        offset
    };
    while paren_count > 0 && at(b, *ptr) == b')' {
        *ptr += 1;
        paren_count -= 1;
    }
    retval
}

/// `TIMELIB_PROCESS_YEAR()`: two-digit years become 1970..2069.
pub(crate) fn process_year(x: &mut i64, l: i32) {
    if *x == UNSET || l >= 4 {
        // (x) = 0;
    } else if *x < 100 {
        if *x < 70 {
            *x += 2000;
        } else {
            *x += 1900;
        }
    }
}

/// A fresh `timelib_time` with the parsers' initial UNSET fields.
fn unset_time() -> Time {
    let mut t = Time::new();
    t.y = UNSET;
    t.d = UNSET;
    t.m = UNSET;
    t.h = UNSET;
    t.i = UNSET;
    t.s = UNSET;
    t.us = UNSET;
    t.z = UNSET as i32;
    t.dst = UNSET as i32;
    t.is_localtime = 0;
    t.zone_type = 0;
    t
}

/// Port of `timelib_strtotime()` (PHPSRC/ext/date/lib/parse_date.re): parses `input` into a [`Time`] whose
/// unparsed fields are [`UNSET`], plus the errors and warnings found.
pub fn strtotime(
    input: &[u8],
    tzdb: &TzDb,
    tz_get_wrapper: &mut TzGetWrapper<'_>,
) -> (Time, ErrorContainer) {
    let len = input.len();
    let mut s = 0usize;
    let mut e: isize = len as isize - 1;

    if len > 0 {
        while is_c_space(at(input, s)) && (s as isize) <= e {
            s += 1;
        }
        while e >= 0 && is_c_space(at(input, e as usize)) && e > s as isize {
            e -= 1;
        }
    }
    if e - (s as isize) < 0 {
        let mut scanner = Scanner {
            str: Vec::new(),
            lim: 0,
            cur: 0,
            tok: None,
            errors: ErrorContainer::default(),
            time: Time::new(),
            tzdb,
        };
        scanner.add_error(ERR_EMPTY_STRING, "Empty string");
        let mut t = scanner.time;
        t.y = UNSET;
        t.d = UNSET;
        t.m = UNSET;
        t.h = UNSET;
        t.i = UNSET;
        t.s = UNSET;
        t.us = UNSET;
        t.dst = UNSET as i32;
        t.z = UNSET as i32;
        t.is_localtime = 0;
        t.zone_type = 0;
        return (t, scanner.errors);
    }
    let e = (e + 1) as usize;

    let mut buf = Vec::with_capacity(e - s + scanner::YYMAXFILL);
    buf.extend_from_slice(&input[s..e]);
    buf.resize(e - s + scanner::YYMAXFILL, 0);
    let mut time = unset_time();
    time.relative.days = UNSET;
    let lim = buf.len();
    let mut sc = Scanner {
        str: buf,
        lim,
        cur: 0,
        tok: None,
        errors: ErrorContainer::default(),
        time,
        tzdb,
    };

    loop {
        let t = scanner::scan(&mut sc, tz_get_wrapper);
        if t == EOI {
            break;
        }
    }

    // do funky checking whether the parsed time was valid time
    if sc.time.have_time != 0 && !valid_time(sc.time.h, sc.time.i, sc.time.s) {
        sc.add_warning(WARN_INVALID_TIME, "The parsed time was invalid");
    }
    // do funky checking whether the parsed date was valid date
    if sc.time.have_date != 0 && !valid_date(sc.time.y, sc.time.m, sc.time.d) {
        sc.add_warning(WARN_INVALID_DATE, "The parsed date was invalid");
    }

    (sc.time, sc.errors)
}

/// [`strtotime`] with the builtin database and the process-wide zone cache (PHP's configuration).
pub fn strtotime_builtin(input: &[u8]) -> (Time, ErrorContainer) {
    let cache = TzCache::builtin();
    strtotime(input, cache.tzdb(), &mut |name: &str, _db: &TzDb| {
        cache.get(name)
    })
}

/// `timelib_format_specifier_code`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FormatSpecifierCode {
    /// `+`
    AllowExtraCharacters,
    /// `#`
    AnySeparator,
    /// `j`
    DayTwoDigit,
    /// `d`
    DayTwoDigitPadded,
    /// ISO day of week (not mapped by default)
    DayOfWeekIso,
    /// day of week (not mapped by default)
    DayOfWeek,
    /// `z`
    DayOfYear,
    /// `S`
    DaySuffix,
    /// end of map
    End,
    /// `U`
    EpochSeconds,
    /// `\`
    Escape,
    /// `h`
    HourTwoDigit12Max,
    /// `g`
    HourTwoDigit12MaxPadded,
    /// `H`
    HourTwoDigit24Max,
    /// `G`
    HourTwoDigit24MaxPadded,
    /// any other character
    Literal,
    /// `a`, `A`
    Meridian,
    /// `u`
    MicrosecondSixDigit,
    /// `v`
    MillisecondThreeDigit,
    /// `i`
    MinuteTwoDigit,
    /// `n`
    MonthTwoDigit,
    /// `m`
    MonthTwoDigitPadded,
    /// `?`
    RandomChar,
    /// `!`
    ResetAll,
    /// `|`
    ResetAllWhenNotSet,
    /// `s`
    SecondTwoDigit,
    /// `;`, `:`, `/`, `.`, `,`, `-`, `(`, `)`
    Separator,
    /// `*`
    SkipToSeparator,
    /// `D`
    TextualDay3Letter,
    /// `l`
    TextualDayFull,
    /// `M`
    TextualMonth3Letter,
    /// `F`
    TextualMonthFull,
    /// `e`, `P`, `p`, `T`, `O`
    TimezoneOffset,
    /// minutes offset (not mapped by default)
    TimezoneOffsetMinutes,
    /// ISO week (not mapped by default)
    WeekOfYearIso,
    /// week (not mapped by default)
    WeekOfYear,
    /// space
    Whitespace,
    /// `y`
    YearTwoDigit,
    /// `Y`
    YearFourDigit,
    /// `x`, `X`
    YearExpanded,
    /// ISO year (not mapped by default)
    YearIso,
}

use FormatSpecifierCode as F;

/// `default_format_map` (PHPSRC/ext/date/lib/parse_date.re).
pub static DEFAULT_FORMAT_MAP: [(u8, FormatSpecifierCode); 46] = [
    (b'+', F::AllowExtraCharacters),
    (b'#', F::AnySeparator),
    (b'j', F::DayTwoDigit),
    (b'd', F::DayTwoDigitPadded),
    (b'z', F::DayOfYear),
    (b'S', F::DaySuffix),
    (b'U', F::EpochSeconds),
    (b'\\', F::Escape),
    (b'h', F::HourTwoDigit12Max),
    (b'g', F::HourTwoDigit12MaxPadded),
    (b'H', F::HourTwoDigit24Max),
    (b'G', F::HourTwoDigit24MaxPadded),
    (b'a', F::Meridian),
    (b'A', F::Meridian),
    (b'u', F::MicrosecondSixDigit),
    (b'v', F::MillisecondThreeDigit),
    (b'i', F::MinuteTwoDigit),
    (b'n', F::MonthTwoDigit),
    (b'm', F::MonthTwoDigitPadded),
    (b'?', F::RandomChar),
    (b'!', F::ResetAll),
    (b'|', F::ResetAllWhenNotSet),
    (b's', F::SecondTwoDigit),
    (b';', F::Separator),
    (b':', F::Separator),
    (b'/', F::Separator),
    (b'.', F::Separator),
    (b',', F::Separator),
    (b'-', F::Separator),
    (b'(', F::Separator),
    (b')', F::Separator),
    (b'*', F::SkipToSeparator),
    (b'D', F::TextualDay3Letter),
    (b'l', F::TextualDayFull),
    (b'M', F::TextualMonth3Letter),
    (b'F', F::TextualMonthFull),
    (b'e', F::TimezoneOffset),
    (b'P', F::TimezoneOffset),
    (b'p', F::TimezoneOffset),
    (b'T', F::TimezoneOffset),
    (b'O', F::TimezoneOffset),
    (b' ', F::Whitespace),
    (b'y', F::YearTwoDigit),
    (b'Y', F::YearFourDigit),
    (b'x', F::YearExpanded),
    (b'X', F::YearExpanded),
];

/// `timelib_format_config`.
#[derive(Clone, Copy, Debug)]
pub struct FormatConfig<'a> {
    /// Specifier map (the C list is terminated by `'\0'`).
    pub format_map: &'a [(u8, FormatSpecifierCode)],
    /// Format specifiers must be preceded by this character if not NUL.
    pub prefix_char: u8,
}

/// `default_format_config`.
pub static DEFAULT_FORMAT_CONFIG: FormatConfig<'static> = FormatConfig {
    format_map: &DEFAULT_FORMAT_MAP,
    prefix_char: 0,
};

/// `timelib_lookup_format()`.
fn lookup_format(input: u8, format_map: &[(u8, FormatSpecifierCode)]) -> FormatSpecifierCode {
    // The C loop stops at the terminating '\0' entry, so NUL never matches.
    if input == 0 {
        return F::Literal;
    }
    format_map
        .iter()
        .find(|(c, _)| *c == input)
        .map_or(F::Literal, |(_, code)| *code)
}

/// `timelib_time_reset_fields()`.
fn time_reset_fields(time: &mut Time) {
    time.y = 1970;
    time.m = 1;
    time.d = 1;
    time.h = 0;
    time.i = 0;
    time.s = 0;
    time.us = 0;
    time.tz_info = None;
}

/// `timelib_time_reset_unset_fields()`.
fn time_reset_unset_fields(time: &mut Time) {
    if time.y == UNSET {
        time.y = 1970;
    }
    if time.m == UNSET {
        time.m = 1;
    }
    if time.d == UNSET {
        time.d = 1;
    }
    if time.h == UNSET {
        time.h = 0;
    }
    if time.i == UNSET {
        time.i = 0;
    }
    if time.s == UNSET {
        time.s = 0;
    }
    if time.us == UNSET {
        time.us = 0;
    }
}

/// Port of `timelib_parse_from_format()` (PHPSRC/ext/date/lib/parse_date.re): `DateTime::createFromFormat()`.
pub fn parse_from_format(
    format: &[u8],
    string: &[u8],
    tzdb: &TzDb,
    tz_get_wrapper: &mut TzGetWrapper<'_>,
) -> (Time, ErrorContainer) {
    parse_from_format_with_map(format, string, tzdb, tz_get_wrapper, &DEFAULT_FORMAT_CONFIG)
}

/// Port of `timelib_parse_from_format_with_map()` (PHPSRC/ext/date/lib/parse_date.re).
///
/// Both `format` and `string` are read as C strings: an embedded NUL ends them.
pub fn parse_from_format_with_map(
    format: &[u8],
    string: &[u8],
    tzdb: &TzDb,
    tz_get_wrapper: &mut TzGetWrapper<'_>,
    format_config: &FormatConfig<'_>,
) -> (Time, ErrorContainer) {
    let mut fbuf = format.to_vec();
    fbuf.push(0);
    let mut sbuf = string.to_vec();
    sbuf.push(0);
    let f = &fbuf[..];
    let st = &sbuf[..];

    let mut fptr = 0usize;
    let mut ptr = 0usize;
    let mut allow_extra = false;
    let mut prefix_found = false;
    let mut iso_year: i32 = UNSET as i32;
    let mut iso_week_of_year: i32 = UNSET as i32;
    let mut iso_day_of_week: i32 = UNSET as i32;
    let prefix_char = format_config.prefix_char;
    let format_map = format_config.format_map;

    let mut errors = ErrorContainer::default();
    let mut time = unset_time();

    // Loop over the format string
    while at(f, fptr) != 0 && at(st, ptr) != 0 {
        let begin = ptr;

        if prefix_char != 0 {
            // There are 2 cases where the input string and format string should match the next literal:
            //
            // 1. No prefix has been specified yet in the format, so expect 1:1 match.
            // 2. Sequential prefix characters indicating that the second prefix is escaped. (e.g. "%%" is
            //    expecting literal "%")
            if (!prefix_found && at(f, fptr) != prefix_char)
                || (prefix_found && at(f, fptr) == prefix_char)
            {
                if at(f, fptr) != at(st, ptr) {
                    add_pbf_error(
                        &mut errors,
                        ERR_FORMAT_LITERAL_MISMATCH,
                        "Format literal not found",
                        st,
                        begin,
                    );
                }
                ptr += 1;
                fptr += 1;
                prefix_found = false;
                continue;
            }

            if at(f, fptr) == prefix_char {
                fptr += 1;
                prefix_found = true;
                continue;
            }

            // Fall through case is that the prefix has been found and the next character is the format
            // specifier.
            prefix_found = false;
        }

        match lookup_format(at(f, fptr), format_map) {
            F::TextualDay3Letter | F::TextualDayFull => {
                // three letter day / full day
                match lookup_relunit(st, &mut ptr) {
                    None => {
                        add_pbf_error(
                            &mut errors,
                            ERR_NO_TEXTUAL_DAY,
                            "A textual day could not be found",
                            st,
                            begin,
                        );
                    }
                    Some(tmprel) => {
                        time.have_relative = 1;
                        time.relative.have_weekday_relative = 1;
                        time.relative.weekday = tmprel.multiplier;
                        time.relative.weekday_behavior = 1;
                    }
                }
            }
            F::DayTwoDigit | F::DayTwoDigitPadded => {
                // two digit day, with or without leading zero
                check_number(&mut errors, st, ptr, begin);
                time.d = get_nr(st, &mut ptr, 2);
                if time.d == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_DAY,
                        "A two digit day could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                }
            }
            F::DaySuffix => {
                // day suffix, ignored, nor checked
                skip_day_suffix(st, &mut ptr);
            }
            F::DayOfYear => {
                // day of year - resets month (0 based) - also initializes everything else to !TIMELIB_UNSET
                check_number(&mut errors, st, ptr, begin);
                if time.y == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_MERIDIAN_BEFORE_HOUR,
                        "A 'day of year' can only come after a year has been found",
                        st,
                        begin,
                    );
                }
                let tmp = get_nr(st, &mut ptr, 3);
                if tmp == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_THREE_DIGIT_DAY_OF_YEAR,
                        "A three digit day-of-year could not be found",
                        st,
                        begin,
                    );
                } else if time.y != UNSET {
                    time.have_date = 1;
                    time.m = 1;
                    time.d = tmp + 1;
                    time.do_normalize();
                }
            }
            F::MonthTwoDigit | F::MonthTwoDigitPadded => {
                check_number(&mut errors, st, ptr, begin);
                time.m = get_nr(st, &mut ptr, 2);
                if time.m == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_MONTH,
                        "A two digit month could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                }
            }
            F::TextualMonth3Letter | F::TextualMonthFull => {
                let tmp = lookup_month(st, &mut ptr);
                if tmp == 0 {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TEXTUAL_MONTH,
                        "A textual month could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                    time.m = tmp;
                }
            }
            F::YearTwoDigit => {
                let mut length = 0;
                check_number(&mut errors, st, ptr, begin);
                time.y = get_nr_ex(st, &mut ptr, 2, &mut length);
                if time.y == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_YEAR,
                        "A two digit year could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                    process_year(&mut time.y, length);
                }
            }
            F::YearFourDigit => {
                check_number(&mut errors, st, ptr, begin);
                time.y = get_nr(st, &mut ptr, 4);
                if time.y == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_FOUR_DIGIT_YEAR,
                        "A four digit year could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                }
            }
            F::YearExpanded => {
                // optional symbol, followed by up to 19 digits
                check_signed_number(&mut errors, st, ptr, begin);
                let mut sc = Scanner {
                    str: Vec::new(),
                    lim: 0,
                    cur: 0,
                    tok: None,
                    errors: std::mem::take(&mut errors),
                    time: Time::new(),
                    tzdb,
                };
                time.y = get_signed_nr_pbf(&mut sc, st, &mut ptr, 19);
                errors = sc.errors;
                if time.y == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_FOUR_DIGIT_YEAR,
                        "An expanded digit year could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                }
            }
            F::HourTwoDigit12Max | F::HourTwoDigit12MaxPadded => {
                check_number(&mut errors, st, ptr, begin);
                time.h = get_nr(st, &mut ptr, 2);
                if time.h == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_HOUR,
                        "A two digit hour could not be found",
                        st,
                        begin,
                    );
                } else if time.h > 12 {
                    add_pbf_error(
                        &mut errors,
                        ERR_HOUR_LARGER_THAN_12,
                        "Hour cannot be higher than 12",
                        st,
                        begin,
                    );
                } else {
                    time.have_time = 1;
                }
            }
            F::HourTwoDigit24MaxPadded | F::HourTwoDigit24Max => {
                check_number(&mut errors, st, ptr, begin);
                time.h = get_nr(st, &mut ptr, 2);
                if time.h == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_HOUR,
                        "A two digit hour could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_time = 1;
                }
            }
            F::Meridian => {
                // am/pm/a.m./p.m. AM/PM/A.M./P.M.
                if time.h == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_MERIDIAN_BEFORE_HOUR,
                        "Meridian can only come after an hour has been found",
                        st,
                        begin,
                    );
                }
                let tmp = meridian_with_check(st, &mut ptr, time.h);
                if tmp == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_MERIDIAN,
                        "A meridian could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_time = 1;
                    if time.h != UNSET {
                        time.h += tmp;
                    }
                }
            }
            F::MinuteTwoDigit => {
                // two digit minute, with leading zero
                let mut length = 0;
                check_number(&mut errors, st, ptr, begin);
                let min = get_nr_ex(st, &mut ptr, 2, &mut length);
                if min == UNSET || length != 2 {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_MINUTE,
                        "A two digit minute could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_time = 1;
                    time.i = min;
                }
            }
            F::SecondTwoDigit => {
                // two digit second, with leading zero
                let mut length = 0;
                check_number(&mut errors, st, ptr, begin);
                let sec = get_nr_ex(st, &mut ptr, 2, &mut length);
                if sec == UNSET || length != 2 {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_SECOND,
                        "A two digit second could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_time = 1;
                    time.s = sec;
                }
            }
            F::MicrosecondSixDigit => {
                // up to six digit microsecond
                check_number(&mut errors, st, ptr, begin);
                let tptr = ptr;
                let f = get_nr(st, &mut ptr, 6);
                if f == UNSET || ptr - tptr < 1 {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_SIX_DIGIT_MICROSECOND,
                        "A six digit microsecond could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.us = f64_to_sll(f as f64 * pow10(6 - (ptr - tptr) as i64));
                }
            }
            F::MillisecondThreeDigit => {
                // up to three digit millisecond
                check_number(&mut errors, st, ptr, begin);
                let tptr = ptr;
                let f = get_nr(st, &mut ptr, 3);
                if f == UNSET || ptr - tptr < 1 {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_THREE_DIGIT_MILLISECOND,
                        "A three digit millisecond could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.us = f64_to_sll(f as f64 * pow10(3 - (ptr - tptr) as i64) * 1000.0);
                }
            }
            F::Whitespace => {
                // any sort of whitespace (' ' and \t)
                eat_spaces(st, &mut ptr);
            }
            F::EpochSeconds => {
                // epoch seconds
                check_signed_number(&mut errors, st, ptr, begin);
                let mut sc = Scanner {
                    str: Vec::new(),
                    lim: 0,
                    cur: 0,
                    tok: None,
                    errors: std::mem::take(&mut errors),
                    time: Time::new(),
                    tzdb,
                };
                let tmp = get_signed_nr_pbf(&mut sc, st, &mut ptr, 24);
                errors = sc.errors;
                time.have_zone = 1;
                time.sse = tmp;
                time.is_localtime = 1;
                time.zone_type = ZONETYPE_OFFSET;
                time.z = 0;
                time.dst = 0;
                time.update_from_sse();
            }
            F::AnySeparator => {
                // separation symbol
                if lookup_format(at(st, ptr), format_map) != F::Separator {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_SEP_SYMBOL,
                        "The separation symbol ([;:/.,-]) could not be found",
                        st,
                        begin,
                    );
                } else {
                    ptr += 1;
                }
            }
            F::Separator => {
                if at(st, ptr) != at(f, fptr) {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_SEP_SYMBOL,
                        "The separation symbol could not be found",
                        st,
                        begin,
                    );
                } else {
                    ptr += 1;
                }
            }
            F::ResetAll => {
                // reset all fields to default
                time_reset_fields(&mut time);
            }
            F::ResetAllWhenNotSet => {
                // reset all fields to default when not set
                time_reset_unset_fields(&mut time);
            }
            F::RandomChar => {
                ptr += 1;
            }
            F::Escape => {
                // escaped char
                if at(f, fptr + 1) == 0 {
                    add_pbf_error(
                        &mut errors,
                        ERR_EXPECTED_ESCAPE_CHAR,
                        "Escaped character expected",
                        st,
                        begin,
                    );
                } else {
                    fptr += 1;
                    if at(st, ptr) != at(f, fptr) {
                        add_pbf_error(
                            &mut errors,
                            ERR_NO_ESCAPED_CHAR,
                            "The escaped character could not be found",
                            st,
                            begin,
                        );
                    } else {
                        ptr += 1;
                    }
                }
            }
            F::SkipToSeparator => {
                // random chars until a separator or number ([ \t.,:;/-0123456789])
                eat_until_separator(st, &mut ptr);
            }
            F::AllowExtraCharacters => {
                // allow extra chars in the format
                allow_extra = true;
            }
            F::YearIso => {
                iso_year = get_nr(st, &mut ptr, 4) as i32;
                if i64::from(iso_year) == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_FOUR_DIGIT_YEAR_ISO,
                        "A four digit ISO year could not be found",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                }
            }
            F::WeekOfYearIso => {
                iso_week_of_year = get_nr(st, &mut ptr, 2) as i32;
                if i64::from(iso_week_of_year) == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_TWO_DIGIT_WEEK,
                        "A two digit ISO week could not be found",
                        st,
                        begin,
                    );
                } else if !(1..=53).contains(&iso_week_of_year) {
                    // Range is 1 - 53  for ISO week of year
                    add_pbf_error(
                        &mut errors,
                        ERR_INVALID_WEEK,
                        "ISO Week must be between 1 and 53",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                }
            }
            F::DayOfWeekIso => {
                iso_day_of_week = get_nr(st, &mut ptr, 1) as i32;
                if i64::from(iso_day_of_week) == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_NO_DAY_OF_WEEK,
                        "A single digit day of week could not be found",
                        st,
                        begin,
                    );
                } else if !(1..=7).contains(&iso_day_of_week) {
                    add_pbf_error(
                        &mut errors,
                        ERR_INVALID_DAY_OF_WEEK,
                        "Day of week must be between 1 and 7",
                        st,
                        begin,
                    );
                } else {
                    time.have_date = 1;
                }
            }
            F::TimezoneOffset => {
                // timezone
                let mut tz_not_found = false;
                let mut dst = time.dst;
                time.z = parse_zone(
                    st,
                    &mut ptr,
                    &mut dst,
                    &mut time,
                    &mut tz_not_found,
                    tzdb,
                    tz_get_wrapper,
                ) as i32;
                if tz_not_found {
                    add_pbf_error(
                        &mut errors,
                        ERR_TZID_NOT_FOUND,
                        "The timezone could not be found in the database",
                        st,
                        begin,
                    );
                } else {
                    time.have_zone = 1;
                }
            }
            F::TimezoneOffsetMinutes => {
                // timezone format +/-mmm
                time.z = parse_tz_minutes(st, &mut ptr, &mut time) as i32;
                if i64::from(time.z) == UNSET {
                    add_pbf_error(
                        &mut errors,
                        ERR_INVALID_TZ_OFFSET,
                        "Invalid timezone offset in minutes",
                        st,
                        begin,
                    );
                } else {
                    time.have_zone = 1;
                }
            }
            F::Literal | F::End | F::DayOfWeek | F::WeekOfYear => {
                if at(f, fptr) != at(st, ptr) {
                    add_pbf_error(
                        &mut errors,
                        ERR_WRONG_FORMAT_SEP,
                        "The format separator does not match",
                        st,
                        begin,
                    );
                }
                ptr += 1;
            }
        }
        fptr += 1;
    }
    if at(st, ptr) != 0 {
        if allow_extra {
            add_pbf_warning(&mut errors, WARN_TRAILING_DATA, "Trailing data", st, ptr);
        } else {
            add_pbf_error(&mut errors, ERR_TRAILING_DATA, "Trailing data", st, ptr);
        }
    }

    if at(f, fptr) != 0 {
        // Trailing reset specifiers are valid.
        let mut done = false;
        while at(f, fptr) != 0 && !done {
            match lookup_format(at(f, fptr), format_map) {
                F::ResetAll => time_reset_fields(&mut time),
                F::ResetAllWhenNotSet => time_reset_unset_fields(&mut time),
                F::AllowExtraCharacters => {}
                _ => {
                    add_pbf_error(
                        &mut errors,
                        ERR_DATA_MISSING,
                        "Not enough data available to satisfy format",
                        st,
                        ptr,
                    );
                    done = true;
                }
            }
            fptr += 1;
        }
    }

    // clean up a bit
    if time.h != UNSET || time.i != UNSET || time.s != UNSET || time.us != UNSET {
        if time.h == UNSET {
            time.h = 0;
        }
        if time.i == UNSET {
            time.i = 0;
        }
        if time.s == UNSET {
            time.s = 0;
        }
        if time.us == UNSET {
            time.us = 0;
        }
    }

    let iso_unset = UNSET as i32;
    // Check for mixing of ISO dates with natural dates.
    if time.y != UNSET
        && (iso_week_of_year != iso_unset || iso_year != iso_unset || iso_day_of_week != iso_unset)
    {
        add_pbf_error(
            &mut errors,
            ERR_MIX_ISO_WITH_NATURAL,
            "Mixing of ISO dates with natural dates is not allowed",
            st,
            ptr,
        );
    }
    if iso_year != iso_unset && (time.y != UNSET || time.m != UNSET || time.d != UNSET) {
        add_pbf_error(
            &mut errors,
            ERR_MIX_ISO_WITH_NATURAL,
            "Mixing of ISO dates with natural dates is not allowed",
            st,
            ptr,
        );
    }

    // Convert ISO values
    if iso_year != iso_unset {
        // Default week of year and day of week to 1.
        if iso_week_of_year == iso_unset {
            iso_week_of_year = 1;
        }
        if iso_day_of_week == iso_unset {
            iso_day_of_week = 1;
        }
        let (y, m, d) = date_from_isodate(
            i64::from(iso_year),
            i64::from(iso_week_of_year),
            i64::from(iso_day_of_week),
        );
        time.y = y;
        time.m = m;
        time.d = d;
    } else if iso_week_of_year != iso_unset || iso_day_of_week != iso_unset {
        add_pbf_warning(
            &mut errors,
            WARN_INVALID_DATE,
            "The parsed date was invalid",
            st,
            ptr,
        );
    }

    // do funky checking whether the parsed time was valid time
    if time.h != UNSET && time.i != UNSET && time.s != UNSET && !valid_time(time.h, time.i, time.s)
    {
        add_pbf_warning(
            &mut errors,
            WARN_INVALID_TIME,
            "The parsed time was invalid",
            st,
            ptr,
        );
    }
    // do funky checking whether the parsed date was valid date
    if time.y != UNSET && time.m != UNSET && time.d != UNSET && !valid_date(time.y, time.m, time.d)
    {
        add_pbf_warning(
            &mut errors,
            WARN_INVALID_DATE,
            "The parsed date was invalid",
            st,
            ptr,
        );
    }

    (time, errors)
}

/// `TIMELIB_CHECK_NUMBER`.
fn check_number(errors: &mut ErrorContainer, st: &[u8], ptr: usize, begin: usize) {
    // `strchr("0123456789", c) == NULL` is false for NUL as well.
    if !matches!(at(st, ptr), b'0'..=b'9' | 0) {
        add_pbf_error(
            errors,
            ERR_UNEXPECTED_DATA,
            "Unexpected data found.",
            st,
            begin,
        );
    }
}

/// `TIMELIB_CHECK_SIGNED_NUMBER`.
fn check_signed_number(errors: &mut ErrorContainer, st: &[u8], ptr: usize, begin: usize) {
    if !matches!(at(st, ptr), b'+' | b'-' | b'0'..=b'9' | 0) {
        add_pbf_error(
            errors,
            ERR_UNEXPECTED_DATA,
            "Unexpected data found.",
            st,
            begin,
        );
    }
}

/// `timelib_get_signed_nr()` called from the format parser, where `add_error()` sees `s->tok == NULL` and so
/// records position 0 and character NUL.
fn get_signed_nr_pbf(sc: &mut Scanner<'_>, st: &[u8], ptr: &mut usize, max_length: i32) -> i64 {
    get_signed_nr(sc, st, ptr, max_length)
}

impl Time {
    /// Port of `timelib_fill_holes()` (PHPSRC/ext/date/lib/parse_date.re): fills [`UNSET`] fields of a parsed
    /// time from `now`.
    ///
    /// With [`NO_CLONE`] (what PHP always passes) `now`'s zone data is shared; without it the zone is copied
    /// with [`TzInfo::timelib_clone`], which, as in C, drops the parsed POSIX rules and the location.
    pub fn fill_holes(&mut self, now: &Time, options: i32) {
        let parsed = self;
        if (options & OVERRIDE_TIME) == 0 && parsed.have_date != 0 && parsed.have_time == 0 {
            parsed.h = 0;
            parsed.i = 0;
            parsed.s = 0;
            parsed.us = 0;
        }
        if parsed.y != UNSET
            || parsed.m != UNSET
            || parsed.d != UNSET
            || parsed.h != UNSET
            || parsed.i != UNSET
            || parsed.s != UNSET
        {
            if parsed.us == UNSET {
                parsed.us = 0;
            }
        } else if parsed.us == UNSET {
            parsed.us = if now.us != UNSET { now.us } else { 0 };
        }
        if parsed.y == UNSET {
            parsed.y = if now.y != UNSET { now.y } else { 0 };
        }
        if parsed.m == UNSET {
            parsed.m = if now.m != UNSET { now.m } else { 0 };
        }
        if parsed.d == UNSET {
            parsed.d = if now.d != UNSET { now.d } else { 0 };
        }
        if parsed.h == UNSET {
            parsed.h = if now.h != UNSET { now.h } else { 0 };
        }
        if parsed.i == UNSET {
            parsed.i = if now.i != UNSET { now.i } else { 0 };
        }
        if parsed.s == UNSET {
            parsed.s = if now.s != UNSET { now.s } else { 0 };
        }

        if parsed.tz_info.is_none() {
            parsed.tz_info = match &now.tz_info {
                Some(tz) if (options & NO_CLONE) == 0 => Some(Arc::new(tz.timelib_clone())),
                other => other.clone(),
            };

            if i64::from(parsed.z) == UNSET {
                parsed.z = if i64::from(now.z) != UNSET { now.z } else { 0 };
            }
            if i64::from(parsed.dst) == UNSET {
                parsed.dst = if i64::from(now.dst) != UNSET {
                    now.dst
                } else {
                    0
                };
            }

            if parsed.tz_abbr.is_none() {
                parsed.tz_abbr = now.tz_abbr.clone();
            }
        }

        if parsed.zone_type == 0 && now.zone_type != 0 {
            parsed.zone_type = now.zone_type;
            parsed.is_localtime = 1;
        }
    }
}

